import styles from './SummaryCard.module.css';
import { useState, useEffect } from 'react';

const SummaryCard = () => {
  const [financialData, setFinancialData] = useState({
    totalIncome: 0,
    totalExpenses: 0,
    balance: 0,
    currentBalance: 0,
  });

  // Cargar datos al inicio y escuchar cambios en localStorage
  useEffect(() => {
    const loadData = () => {
      const savedData = localStorage.getItem('financialData');
      if (savedData) setFinancialData(JSON.parse(savedData));
    };

    loadData(); // Carga inicial
    window.addEventListener('storage', loadData); // Escuchar cambios desde otras pestañas

    return () => window.removeEventListener('storage', loadData); // Limpiar listener
  }, []);

  return (
    <div className={styles.card}>
      <h3>Resumen Financiero</h3>
      <div className={styles.summaryItem}>
        <p>Ingresos: ${financialData.totalIncome.toFixed(2)}</p>
      </div>
      <div className={styles.summaryItem}>
        <p>Gastos: ${financialData.totalExpenses.toFixed(2)}</p>
      </div>
      <div className={styles.summaryItem}>
        <p>Balance: ${financialData.balance.toFixed()}</p>
      </div>
      <div className={styles.summaryItem}>
        <p>Saldo Actual: ${financialData.currentBalance.toFixed(2)}</p>
      </div>
    </div>
  );
};

export default SummaryCard;
